/* Decorative surface reveals must not ramp the backdrop's opacity or move edges. */
#game-hub-control-center,#game-hub-control-center .gcc-settings,
#game-hub-control-center .gcc-section

`
/* Paint only: retain every dock hitbox, action, badge and position. */
#game-hub-control-center .gcc-dock .gcc-dock-row

new MutationObserver((records) => {
      for (const rec of records) {
        const target = rec.target as HTMLElement & FocusHook;
        const was = (rec.oldValue ?? "").split(" ").includes(FOCUSED_CLASS);
        if (was || !target.classList.contains(FOCUSED_CLASS)) continue;
        // The home row moves itself (see Ps5Home's slideTo), so it's left alone here.
        const row = target.closest<HTMLElement>(".ghd-row, .ghd-chips");
        if (row && !row.classList.contains("ghd-row-anchor")) keepInView(row, target, "x");
        const column = target.closest<HTMLElement>(".ghd-grid, .ghd-cards");
        if (column && !column.classList.contains("ghl-grid")) keepInView(column, target, "y");
        target.__psdFocus?.();
      }
    })

/* Home row tiles (see .ghd-home-row). The art box is drawn at full size and scaled down when not
   selected, so the picture stays sharp when it grows. */
.ghd-tile-home

new win.MutationObserver(records => { for (const r of records) {
        const el = r.target;
        if (r.type === 'attributes' && el.matches?.('.ghd-focused,.gbs-focus,.gpfocus') && el.closest(scopes) && !String(r.oldValue).split(' ').some(c => ['ghd-focused', 'gbs-focus', 'gpfocus'].includes(c))) {
            mark(el);
            return;
        }
        if (active && (el === active || el.contains?.(active) || !active.isConnected))
            schedule();
    } })

/* Keep the equipped artwork bright; readability belongs to text and cards. */
html[data-gh-profile] .responsive_page_template_content>.profile_page::before,
html[data-gh-profile] .responsive_page_template_content>.profile_page::after
